<script setup lang="ts">
import {computed,ref,watch} from 'vue'
import {useRoute,useRouter} from 'vue-router'
import {useSessionStore} from '@/stores/session'
import {useServiceContext} from '@/composables/useServiceContext'
import {ApiError,asApiError} from '@/api/client'
import {channels,directTargetLink,isFeedItem,isPage,isUnread,isReadAll,query,type FeedItem,type Unread,type Channel,type Page} from '@/api/modules/clientServices'
import {businessLink,domains,eventText,getBusiness,type Target} from '@/api/modules/operations'
import ServiceWorkspace from '@/components/ServiceWorkspace.vue'
import '@/styles/operations.css'
const route=useRoute(),router=useRouter(),session=useSessionStore(),ui=useServiceContext(()=>session.selectedId||null),{error,notice,busy,pending}=ui
const notifications=ref<FeedItem[]>([]),cursor=ref<number|null>(null),snapshot=ref<Unread|null>(null),channel=ref<Channel|''>(''),unread=ref(false),loading=ref(false),pendingRead=ref<number|null>(null),checkedPending=ref(false),eventId=computed(()=>Number(route.params.eventId||0)),locked=computed(()=>busy.value||!!pending.value||loading.value)
let initialized=false
function initialize(){initialized=true;void load()}
let serial=0,countSerial=0
async function counts(){const n=++countSerial,s=ui.signature.value;snapshot.value=null;const r=await ui.read('/operations/notifications/unread',isUnread);if(n===countSerial&&s===ui.signature.value)snapshot.value=r}
async function findEvent(id:number){let position:number|null=null;const seen=new Set<number>();for(let page=0;page<10;page++){const r:Page<FeedItem>|null=await ui.read('/operations/notifications/feed'+query({cursor:position,limit:30,unread_only:false}),isPage(isFeedItem,'number'));if(!r)return null;const found=r.items.find(n=>n.id===id);if(found)return found;if(r.next_cursor===null)return null;if(typeof r.next_cursor!=='number'||seen.has(r.next_cursor))throw new ApiError({status:200,code:'UNEXPECTED_RESPONSE_SHAPE',message:'通知分页位置未更新。'});seen.add(r.next_cursor);position=r.next_cursor}notice.value='已查找前 300 条来源事件；请从通知列表继续读取更早事件。';return null}
async function load(more=false){if(!session.selectedId||loading.value||more&&cursor.value===null)return;const n=++serial,old=more?cursor.value:null;loading.value=true;error.value=null;if(!more){notifications.value=[];cursor.value=null}
 try{if(eventId.value){const event=await findEvent(eventId.value);if(n!==serial)return;notifications.value=event?[event]:[];await counts()}else{const r=await ui.read('/operations/notifications/feed'+query({limit:30,unread_only:unread.value,channel:channel.value,cursor:old}),isPage(isFeedItem,'number'));if(n!==serial)return;if(r){if(r.next_cursor!==null&&(typeof r.next_cursor!=='number'||r.next_cursor===old)){ui.fail('通知分页位置没有更新，请刷新列表。')}else{notifications.value=more?[...new Map([...notifications.value,...r.items].map(x=>[x.id,x])).values()]:r.items;cursor.value=r.next_cursor as number|null}}if(!more)await counts()}}catch(e){if(n===serial)error.value=asApiError(e)}finally{if(n===serial)loading.value=false}}
async function markRead(n:FeedItem){if(locked.value||n.read)return;pendingRead.value=n.id;checkedPending.value=false;await ui.write(`/operations/notifications/${n.id}/read`,{},(v):v is {id:number;read:true}=>!!v&&typeof v==='object'&&(v as any).id===n.id&&(v as any).read===true,async()=>{pendingRead.value=null;await load()});if(!pending.value)pendingRead.value=null}
async function checkPending(){if(!pending.value||busy.value||!pendingRead.value)return;loading.value=true;error.value=null;try{const n=await findEvent(pendingRead.value);checkedPending.value=true;if(n?.read){pending.value=null;pendingRead.value=null;notice.value='原通知已经标为已读，已核对；没有重复提交。';loading.value=false;await load()}else notice.value='尚未确认原通知已读。可恢复原请求，继续使用原请求编号和内容。'}catch(e){error.value=asApiError(e)}finally{loading.value=false}}
async function readAll(){const s=snapshot.value;if(locked.value||!s)return;if(Date.parse(s.expires_at)<=Date.now()){notice.value='未读查询已到期，已重新读取。请核对后再次点击全部已读。';await counts();return}const selected=channel.value||null;await ui.write('/operations/notifications/read-all',{snapshot_id:s.snapshot_id,channel:selected},(v):v is ReturnType<typeof readAllResult>=>isReadAll(v)&&v.snapshot_id===s.snapshot_id,async r=>{notice.value=`本次标记 ${r.marked_count} 条提醒，另有 ${r.skipped_count} 条因权限变化跳过。新到提醒不会被本次操作清除。`;await load()});if(error.value?.code==='NOTIFICATION_SNAPSHOT_EXPIRED'){await counts();notice.value='原查询已到期，已重新读取计数。请核对后再次操作；未自动清除新消息。'}}
function readAllResult(){return{snapshot_id:'',as_of:'',marked_count:0,skipped_count:0}}
async function openBusiness(n:FeedItem){if(locked.value)return;const direct=directTargetLink(n.target,true);if(direct){await router.push(direct);return}const t=n.target as Target;if(!Object.hasOwn(domains,t.domain)){ui.fail('该通知的原业务入口尚不能识别，请保留通知并反馈问题。');return}const signature=ui.signature.value;try{const r=await getBusiness(ui.identity(),t);if(signature===ui.signature.value)await router.push(businessLink(t,r))}catch(e){if(signature===ui.signature.value)error.value=asApiError(e)}}
watch(ui.revision,()=>{serial++;notifications.value=[];snapshot.value=null;cursor.value=null;loading.value=false;pendingRead.value=null;checkedPending.value=false;if(initialized&&ui.ready.value)void load()},{flush:'sync'})
watch(()=>[channel.value,unread.value],()=>{notifications.value=[];cursor.value=null;void load()})
</script>
<template><ServiceWorkspace class="operations-workspace" data-gallery="WEB-32-01" error-testid="ops-error" title="我的业务通知" intro="消息按当前办理身份分为四类；通知已读与实际阅读订单会话分别记录。" :locked="busy||!!pending" :error="error" :notice="notice" @ready="initialize"><template #heading><button class="outline" data-testid="ops-refresh" :disabled="locked" @click="load()">刷新当前记录</button></template><div class="service-tabs"><RouterLink to="/operations/notifications">我的通知</RouterLink><RouterLink to="/support/tickets">我的反馈</RouterLink><RouterLink to="/operations/reports">本方报表</RouterLink><RouterLink to="/operations/moderation">留言独立管理</RouterLink><RouterLink to="/operations/audit">只读操作历史</RouterLink></div><section v-if="pending" class="service-pending" data-testid="ops-pending"><h2>原请求结果尚未确认</h2><p>保留原身份、原请求编号和内容。先核对原通知，再恢复原操作。</p><button v-if="pendingRead" class="outline" data-testid="ops-check-pending" :disabled="busy||loading" @click="checkPending">先核对原通知</button><button class="outline" data-testid="ops-retry-pending" :disabled="busy||loading||!!pendingRead&&!checkedPending" @click="ui.retry">恢复原请求</button></section><section class="supply-card"><div v-if="!eventId" class="service-form"><label>消息频道<select v-model="channel" :disabled="locked"><option value="">全部频道</option><option v-for="(name,key) in channels" :key="key" :value="key">{{name}}{{snapshot?' · '+snapshot.channels[key]:''}}</option></select></label><label class="service-check"><input v-model="unread" data-testid="ops-unread-only" type="checkbox" :disabled="locked">只看未读</label></div><p v-if="snapshot" role="status">当前身份未读提醒 {{snapshot.total}} 条。计数时间 {{new Date(snapshot.as_of).toLocaleString()}}。</p><p v-else role="status">未读数量尚未读取成功，请刷新核对。</p><button v-if="!eventId" class="outline" data-testid="ops-read-all" :disabled="locked||!snapshot||snapshot.total===0" @click="readAll">全部已读</button><p class="service-muted">全部已读仅处理本次查询时已获准的{{channel?channels[channel]:'全部频道'}}提醒，不代表已阅读会话或完成原业务。</p><p v-if="loading" role="status">正在读取当前身份通知…</p><div class="table-wrap"><table><thead><tr><th>事件</th><th>原业务对象</th><th>发生时间</th><th>已读状态</th><th>操作</th></tr></thead><tbody><tr v-for="n in notifications" :key="n.id" :class="{'ops-notification-unread':!n.read}"><td><RouterLink :to="`/operations/notifications/${n.id}`">{{eventText(n.event_code)}}</RouterLink><p class="service-muted">{{channels[n.channel]}} · 事件时版本 {{n.object_version}}</p></td><td>{{(domains as Record<string,string>)[n.target.domain]||channels[n.channel]}} · {{n.target.record_id.slice(0,8)}}</td><td><time>{{new Date(n.created_at).toLocaleString()}}</time></td><td>{{n.read?'已读':'未读'}}</td><td><div class="service-actions"><button :data-testid="`ops-open-event-${n.id}`" class="outline" :disabled="locked" @click="openBusiness(n)">读取并打开原业务</button><button v-if="!n.read" :data-testid="`ops-read-event-${n.id}`" class="outline" :disabled="locked" @click="markRead(n)">标记此条已读</button></div></td></tr></tbody></table></div><p v-if="!notifications.length&&!cursor&&!loading&&!error" class="supply-empty">当前范围没有获准可见的通知。</p><p v-if="!notifications.length&&cursor">本页没有可显示项，可继续读取更早事件。</p><button v-if="cursor!==null&&!eventId" class="outline" :disabled="locked" @click="load(true)">继续读取更早事件</button><RouterLink v-if="eventId" to="/operations/notifications" class="button-link outline">返回业务通知</RouterLink></section></ServiceWorkspace></template>
